INSERT INTO _assert SELECT 'empty Protected Users', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"oa"},{"id":"ob"}]');
INSERT INTO _assert SELECT 'absent Protected Users', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''missing-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"oa"},{"id":"ob"}]');
INSERT INTO _assert SELECT 'present direct and transitive Protected Users', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid ENDS WITH ''-525'' AND g.objectid <> ''empty-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"ob"}]');
INSERT INTO _assert SELECT 'delegable accounts with empty Protected Users', json(cypher('MATCH (m:OptUser) WHERE m:OptTier AND m.enabled=true AND m.sensitive=false OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"oa"}]');
INSERT INTO _assert SELECT 'optional preserves empty collected list', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' WITH m,COLLECT(n) AS ns RETURN m.objectid AS id,ns,size(ns) AS size ORDER BY id')) = json('[{"id":"oa","ns":[],"size":0},{"id":"ob","ns":[],"size":0}]');
INSERT INTO _assert SELECT 'optional has no synthetic outer users', json(cypher('MATCH (m:OptUser) WHERE m:OptTier AND m.objectid=''missing'' OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[]');
INSERT INTO _assert SELECT 'both fresh endpoints null together', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' RETURN m.objectid AS id,g.objectid AS g,n.objectid AS n ORDER BY id')) = json('[{"id":"oa","g":null,"n":null},{"id":"ob","g":null,"n":null}]');
INSERT INTO _assert SELECT 'fresh endpoint WHERE correlates outer identity', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''live2-525'' AND n.objectid=m.objectid RETURN m.objectid AS id,g.objectid AS g,n.objectid AS n ORDER BY id')) = json('[{"id":"oa","g":"live2-525","n":"oa"},{"id":"ob","g":null,"n":null}]');
INSERT INTO _assert SELECT 'leading optional is one null row', json(cypher('OPTIONAL MATCH (a:OptMissing)-[:OptMember*]->(b:OptBase) RETURN a,b')) = json('[{"a":null,"b":null}]');
INSERT INTO _assert SELECT 'WITH before optional retains outer identity', json(cypher('MATCH(m:OptUser) WITH m OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''empty-525'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"oa"},{"id":"ob"}]');
INSERT INTO _assert SELECT 'optional rejects missing endpoint label', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (a:OptBase)-[:OptMember*]->(b:OptMissing) RETURN m.objectid AS id,a,b ORDER BY id')) = json('[{"id":"oa","a":null,"b":null},{"id":"ob","a":null,"b":null}]');
INSERT INTO _assert SELECT 'optional inline properties are atomic', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (a:OptBase {objectid:''oa''})-[:OptMember*]->(b:OptGroup {objectid:''missing''}) RETURN m.objectid AS id,a,b ORDER BY id')) = json('[{"id":"oa","a":null,"b":null},{"id":"ob","a":null,"b":null}]');
INSERT INTO _assert SELECT 'chained optional rejects whole path', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH p=(a)-[rs:OptMember*1..1]->(b:OptBase)-[ss:OptMember*1..1]->(c:OptBase) WHERE c.objectid=''missing'' RETURN a.objectid AS a,b,c,size(rs) AS rs,size(ss) AS ss,length(p) AS hops')) = json('[{"a":"oa","b":null,"c":null,"rs":null,"ss":null,"hops":null}]');
INSERT INTO _assert SELECT 'chained optional keeps only complete candidates', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH p=(a)-[rs:OptMember*1..1]->(b:OptBase)-[ss:OptMember*1..1]->(c:OptBase) WHERE c.objectid=''live-525'' RETURN a.objectid AS a,b.objectid AS b,c.objectid AS c,length(p) AS hops')) = json('[{"a":"oa","b":"mid","c":"live-525","hops":2}]');
INSERT INTO _assert SELECT 'chained optional cross-endpoint OR', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH p=(a)-[rs:OptMember*1..1]->(b:OptBase)-[ss:OptMember*1..1]->(c:OptBase) WHERE (b.objectid=''mid'' AND c.objectid=''live-525'') OR (b.objectid=''live2-525'' AND c.objectid=''missing'') RETURN b.objectid AS b,c.objectid AS c')) = json('[{"b":"mid","c":"live-525"}]');
INSERT INTO _assert SELECT 'chained optional preserves bound endpoints', json(cypher('MATCH(a:OptUser {objectid:''oa''}),(c:OptGroup {objectid:''live-525''}) OPTIONAL MATCH (a)-[:OptMember*1..1]->(b:OptBase)-[:OptMember*1..1]->(c) WHERE b.objectid=''missing'' RETURN a.objectid AS a,b,c.objectid AS c')) = json('[{"a":"oa","b":null,"c":"live-525"}]');
INSERT INTO _assert SELECT 'comma patterns share one optional unit', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[rs:OptMember*1..1]->(b),(a)-[ss:Missing*1..1]->(c) RETURN a.objectid AS a,b,c,size(rs) AS rs,size(ss) AS ss')) = json('[{"a":"oa","b":null,"c":null,"rs":null,"ss":null}]');
INSERT INTO _assert SELECT 'separate optional clauses keep earlier bindings', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[rs:OptMember*1..1]->(b) OPTIONAL MATCH (a)-[ss:Missing*1..1]->(c) RETURN b.objectid AS b,c,size(rs) AS rs,size(ss) AS ss ORDER BY b')) = json('[{"b":"live2-525","c":null,"rs":1,"ss":null},{"b":"mid","c":null,"rs":1,"ss":null}]');
INSERT INTO _assert SELECT 'optional keeps duplicate outer rows', json(cypher('UNWIND [1,1] AS i OPTIONAL MATCH (a:OptMissing)-[:OptMember*]->(b) RETURN i,a,b')) = json('[{"i":1,"a":null,"b":null},{"i":1,"a":null,"b":null}]');
INSERT INTO _assert SELECT 'WITH-bound endpoint label failure is optional', json(cypher('MATCH (a:OptUser {objectid:''oa''}) WITH a OPTIONAL MATCH (a:OptMissing)-[:OptMember*0..1]->(b) RETURN a.objectid AS a,b')) = json('[{"a":"oa","b":null}]');
INSERT INTO _assert SELECT 'optional zero-hop keeps same endpoint', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH p=(a)-[:Missing*0..0]->(b:OptUser) RETURN a.objectid AS a,b.objectid AS b,length(p) AS hops')) = json('[{"a":"oa","b":"oa","hops":0}]');
INSERT INTO _assert SELECT 'optional null anchor does not invent zero-hop', json(cypher('OPTIONAL MATCH (a:OptMissing) WITH a OPTIONAL MATCH (a)-[:OptMember*0..1]->(b) RETURN a,b')) = json('[{"a":null,"b":null}]');
INSERT INTO _assert SELECT 'optional parallel paths retain multiplicity', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[:Parallel*1..1]->(b) RETURN b.objectid AS b')) = json('[{"b":"mid"},{"b":"mid"}]');
INSERT INTO _assert SELECT 'optional predicates ignore SQL-looking literal', json(cypher('MATCH (m:OptUser) WHERE m:OptTier OPTIONAL MATCH (g:OptGroup)<-[:OptMember*1..]-(n:OptBase) WHERE g.objectid=''_gql_default_alias_1.id LEFT JOIN nodes ON 1=1'' WITH m,COLLECT(n) AS matchingNs WHERE NONE(n IN matchingNs WHERE n.objectid=m.objectid) RETURN m.objectid AS id ORDER BY id')) = json('[{"id":"oa"},{"id":"ob"}]');
INSERT INTO _assert SELECT 'optional segments cannot reuse one relationship', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[:OptMember*1..1]->(b)<-[:OptMember*1..1]-(c) RETURN a.objectid AS a,b,c')) = json('[{"a":"oa","b":null,"c":null}]');
INSERT INTO _assert SELECT 'optional mixed segments cannot reuse one relationship', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[:OptMember]->(b)<-[:OptMember*1..1]-(c) RETURN a.objectid AS a,b,c')) = json('[{"a":"oa","b":null,"c":null}]');
INSERT INTO _assert SELECT 'optional comma patterns cannot reuse one relationship', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH (a)-[:OptMember*1..1]->(b),(c)-[:OptMember*1..1]->(b) RETURN a.objectid AS a,b,c')) = json('[{"a":"oa","b":null,"c":null}]');
INSERT INTO _assert SELECT 'optional projected relationship lists have unique aliases', json(cypher('MATCH (a:OptUser {objectid:''oa''}) MATCH(a)-[r:OptMember]->(b:OptGroup {objectid:''mid''}) MATCH(b)-[s:OptMember]->(c:OptGroup {objectid:''live-525''}) WITH a,b,c,[r] AS rs,[s] AS ss OPTIONAL MATCH (a)-[rs*]->(x),(b)-[ss*]->(y) RETURN x.objectid AS x,y.objectid AS y')) = json('[{"x":"mid","y":"live-525"}]');
INSERT INTO _assert SELECT 'failed optional returns a null path value', json(cypher('MATCH (a:OptUser {objectid:''oa''}) OPTIONAL MATCH p=(a)-[rs:OptMember*1..1]->(b:OptBase)-[ss:OptMember*1..1]->(c:OptBase) WHERE c.objectid=''missing'' RETURN p')) = json('[{"p":null}]');
INSERT INTO _assert SELECT 'optional single table retains both bound endpoints', json(cypher('MATCH(a:OptUser {objectid:''oa''}),(b:OptGroup {objectid:''live-525''}) OPTIONAL MATCH p=(a)-[rs:OptMember*]->(b) RETURN a.objectid AS a,b.objectid AS b,length(p) AS hops,size(rs) AS size')) = json('[{"a":"oa","b":"live-525","hops":2,"size":2}]');
INSERT INTO _assert SELECT 'optional single table preserves missing path and endpoints', json(cypher('MATCH(a:OptUser {objectid:''oa''}),(b:OptGroup {objectid:''live-525''}) OPTIONAL MATCH p=(a)-[rs:Missing*]->(b) RETURN a.objectid AS a,b.objectid AS b,p,rs')) = json('[{"a":"oa","b":"live-525","p":null,"rs":null}]');
INSERT INTO _assert SELECT 'optional single table evaluates list predicate before null extension', json(cypher('MATCH(a:OptUser {objectid:''oa''}),(b:OptGroup {objectid:''live-525''}) OPTIONAL MATCH(a)-[rs:OptMember*]-(b) WHERE rs IS NULL AND a<>b RETURN a.objectid AS a,b.objectid AS b,rs')) = json('[{"a":"oa","b":"live-525","rs":null}]');
